# Write the CLI parser
cat > src/cli.rs << 'RUSTEOF'
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LangArg {
    English,
    English1k,
    English10k,
}

impl LangArg {
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "english" => Some(LangArg::English),
            "english1k" => Some(LangArg::English1k),
            "english10k" => Some(LangArg::English10k),
            _ => None,
        }
    }
}

pub struct Config {
    pub number_of_words: usize,
    pub number_of_secs: Option<u64>,
    pub number_of_sentences: Option<usize>,
    pub supported_language: LangArg,
    pub prompt: Option<String>,
}

pub enum CliResult {
    Config(Config),
    HelpPrinted,
    VersionPrinted,
    Error(String),
}

const HELP_BODY: &str = "thokr 0.4.1
sleek typing tui with visualized results and historical logging

USAGE:
    {PROG} [OPTIONS]

OPTIONS:
    -f, --full-sentences <NUMBER_OF_SENTENCES>
            number of sentences to use in test

    -h, --help
            Print help information

    -l, --supported-language <SUPPORTED_LANGUAGE>
            language to pull words from [default: english] [possible values: english, english1k,
            english10k]

    -p, --prompt <PROMPT>
            custom prompt to use

    -s, --number-of-secs <NUMBER_OF_SECS>
            number of seconds to run test

    -V, --version
            Print version information

    -w, --number-of-words <NUMBER_OF_WORDS>
            number of words to use in test [default: 15]
";

pub fn help_text(prog: &str) -> String {
    HELP_BODY.replace("{PROG}", prog)
}

pub fn version_text() -> String {
    String::from("thokr 0.4.1\n")
}

fn usage_err(prog: &str) -> String {
    format!("\nUSAGE:\n    {} [OPTIONS]\n\nFor more information try --help\n", prog)
}

fn usage_err_with(prog: &str, one_liner: &str) -> String {
    format!("\nUSAGE:\n    {} {}\n\nFor more information try --help\n", prog, one_liner)
}

fn err_unexpected(prog: &str, arg: &str) -> String {
    let hint = if arg.starts_with('-') {
        format!(
            "\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n",
            arg, arg
        )
    } else {
        String::new()
    };
    format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n{}{}",
        arg,
        hint,
        usage_err(prog)
    )
}

fn err_requires_value(prog: &str, long: &str, placeholder: &str) -> String {
    format!(
        "error: The argument '--{} <{}>' requires a value but none was supplied\n{}",
        long,
        placeholder,
        usage_err(prog)
    )
}

fn err_multiple(prog: &str, long: &str, placeholder: &str) -> String {
    format!(
        "error: The argument '--{} <{}>' was provided more than once, but cannot be used multiple times\n{}",
        long,
        placeholder,
        usage_err(prog)
    )
}

fn err_invalid_value(long: &str, placeholder: &str, val: &str, reason: &str) -> String {
    format!(
        "error: Invalid value \"{}\" for '--{} <{}>': {}\n\nFor more information try --help\n",
        val, long, placeholder, reason
    )
}

fn err_bad_lang(prog: &str, val: &str) -> String {
    format!(
        "error: \"{}\" isn't a valid value for '--supported-language <SUPPORTED_LANGUAGE>'\n\t[possible values: english, english1k, english10k]\n{}",
        val,
        usage_err_with(prog, "--supported-language <SUPPORTED_LANGUAGE>")
    )
}

struct OptDef {
    short: char,
    long: &'static str,
    placeholder: Option<&'static str>,
}

const OPTS: &[OptDef] = &[
    OptDef { short: 'f', long: "full-sentences", placeholder: Some("NUMBER_OF_SENTENCES") },
    OptDef { short: 'h', long: "help", placeholder: None },
    OptDef { short: 'l', long: "supported-language", placeholder: Some("SUPPORTED_LANGUAGE") },
    OptDef { short: 'p', long: "prompt", placeholder: Some("PROMPT") },
    OptDef { short: 's', long: "number-of-secs", placeholder: Some("NUMBER_OF_SECS") },
    OptDef { short: 'V', long: "version", placeholder: None },
    OptDef { short: 'w', long: "number-of-words", placeholder: Some("NUMBER_OF_WORDS") },
];

fn find_long(name: &str) -> Option<&'static OptDef> {
    OPTS.iter().find(|o| o.long == name)
}

fn find_short(c: char) -> Option<&'static OptDef> {
    OPTS.iter().find(|o| o.short == c)
}

pub fn parse_args(prog: &str, argv: &[String]) -> CliResult {
    let mut number_of_words: Option<String> = None;
    let mut number_of_secs: Option<String> = None;
    let mut number_of_sentences: Option<String> = None;
    let mut supported_language: Option<String> = None;
    let mut prompt: Option<String> = None;
    let mut help_seen = false;
    let mut version_seen = false;

    let mut iter = argv.iter().enumerate();
    let mut passthrough = false;
    while let Some((_, a)) = iter.next() {
        if passthrough {
            return CliResult::Error(err_unexpected(prog, a));
        }
        if a == "--" {
            passthrough = true;
            continue;
        }
        if a.starts_with("--") {
            // --long or --long=value
            let body = &a[2..];
            let (name, val): (&str, Option<&str>) = if let Some(eq) = body.find('=') {
                (&body[..eq], Some(&body[eq + 1..]))
            } else {
                (body, None)
            };
            let def = match find_long(name) {
                Some(d) => d,
                None => return CliResult::Error(err_unexpected(prog, a)),
            };
            if def.long == "help" {
                if val.is_some() {
                    return CliResult::Error(err_unexpected(prog, a));
                }
                if !version_seen {
                    help_seen = true;
                }
                continue;
            }
            if def.long == "version" {
                if val.is_some() {
                    return CliResult::Error(err_unexpected(prog, a));
                }
                if !help_seen {
                    version_seen = true;
                }
                continue;
            }
            // takes value
            let placeholder = def.placeholder.unwrap();
            let v = if let Some(v) = val {
                v.to_string()
            } else {
                match iter.next() {
                    Some((_, nv)) => nv.clone(),
                    None => {
                        return CliResult::Error(err_requires_value(prog, def.long, placeholder));
                    }
                }
            };
            // store
            match def.long {
                "full-sentences" => {
                    if number_of_sentences.is_some() {
                        return CliResult::Error(err_multiple(prog, def.long, placeholder));
                    }
                    number_of_sentences = Some(v);
                }
                "supported-language" => {
                    if supported_language.is_some() {
                        return CliResult::Error(err_multiple(prog, def.long, placeholder));
                    }
                    supported_language = Some(v);
                }
                "prompt" => {
                    if prompt.is_some() {
                        return CliResult::Error(err_multiple(prog, def.long, placeholder));
                    }
                    prompt = Some(v);
                }
                "number-of-secs" => {
                    if number_of_secs.is_some() {
                        return CliResult::Error(err_multiple(prog, def.long, placeholder));
                    }
                    number_of_secs = Some(v);
                }
                "number-of-words" => {
                    if number_of_words.is_some() {
                        return CliResult::Error(err_multiple(prog, def.long, placeholder));
                    }
                    number_of_words = Some(v);
                }
                _ => unreachable!(),
            }
        } else if a.starts_with('-') && a.len() >= 2 {
            // short options: may be concatenated: -hV, -w10
            let chars: Vec<char> = a[1..].chars().collect();
            let mut i = 0;
            while i < chars.len() {
                let c = chars[i];
                let def = match find_short(c) {
                    Some(d) => d,
                    None => {
                        // Unknown short: format as "-c" error
                        let s = format!("-{}", c);
                        return CliResult::Error(err_unexpected(prog, &s));
                    }
                };
                if def.long == "help" {
                    if !version_seen {
                        help_seen = true;
                    }
                    i += 1;
                    continue;
                }
                if def.long == "version" {
                    if !help_seen {
                        version_seen = true;
                    }
                    i += 1;
                    continue;
                }
                // takes value - rest of chars is the value, else next arg
                let placeholder = def.placeholder.unwrap();
                let rest: String = chars[i + 1..].iter().collect();
                let v = if !rest.is_empty() {
                    // strip a leading '=' if present
                    if rest.starts_with('=') {
                        rest[1..].to_string()
                    } else {
                        rest
                    }
                } else {
                    match iter.next() {
                        Some((_, nv)) => nv.clone(),
                        None => {
                            return CliResult::Error(err_requires_value(prog, def.long, placeholder));
                        }
                    }
                };
                match def.long {
                    "full-sentences" => {
                        if number_of_sentences.is_some() {
                            return CliResult::Error(err_multiple(prog, def.long, placeholder));
                        }
                        number_of_sentences = Some(v);
                    }
                    "supported-language" => {
                        if supported_language.is_some() {
                            return CliResult::Error(err_multiple(prog, def.long, placeholder));
                        }
                        supported_language = Some(v);
                    }
                    "prompt" => {
                        if prompt.is_some() {
                            return CliResult::Error(err_multiple(prog, def.long, placeholder));
                        }
                        prompt = Some(v);
                    }
                    "number-of-secs" => {
                        if number_of_secs.is_some() {
                            return CliResult::Error(err_multiple(prog, def.long, placeholder));
                        }
                        number_of_secs = Some(v);
                    }
                    "number-of-words" => {
                        if number_of_words.is_some() {
                            return CliResult::Error(err_multiple(prog, def.long, placeholder));
                        }
                        number_of_words = Some(v);
                    }
                    _ => unreachable!(),
                }
                // consumed rest for value
                break;
            }
        } else {
            // positional / free arg
            return CliResult::Error(err_unexpected(prog, a));
        }
    }

    if help_seen {
        print!("{}", help_text(prog));
        return CliResult::HelpPrinted;
    }
    if version_seen {
        print!("{}", version_text());
        return CliResult::VersionPrinted;
    }

    // Validate numeric values
    let number_of_words: usize = match number_of_words {
        None => 15,
        Some(s) => match s.parse::<usize>() {
            Ok(v) => v,
            Err(e) => {
                return CliResult::Error(err_invalid_value(
                    "number-of-words",
                    "NUMBER_OF_WORDS",
                    &s,
                    &parse_int_error(&e),
                ));
            }
        },
    };
    let number_of_secs: Option<u64> = match number_of_secs {
        None => None,
        Some(s) => match s.parse::<u64>() {
            Ok(v) => Some(v),
            Err(e) => {
                return CliResult::Error(err_invalid_value(
                    "number-of-secs",
                    "NUMBER_OF_SECS",
                    &s,
