// Minimal terminal/raw-mode helpers using direct libc FFI.

use std::io::{self, Read, Write};

#[repr(C)]
struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

#[repr(C)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

unsafe extern "C" {
    fn isatty(fd: i32) -> i32;
    fn tcgetattr(fd: i32, termios_p: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, opt: i32, termios_p: *const Termios) -> i32;
    fn ioctl(fd: i32, req: u64, ...) -> i32;
    fn read(fd: i32, buf: *mut u8, count: usize) -> isize;
    fn poll(fds: *mut PollFd, nfds: u64, timeout: i32) -> i32;
}

#[repr(C)]
struct PollFd {
    fd: i32,
    events: i16,
    revents: i16,
}

const TCSANOW: i32 = 0;
const TIOCGWINSZ: u64 = 0x5413;
const ICANON: u32 = 0o0000002;
const ECHO: u32 = 0o0000010;
const ISIG: u32 = 0o0000001;
const IXON: u32 = 0o0002000;
const ICRNL: u32 = 0o0000400;
const OPOST: u32 = 0o0000001;
const IEXTEN: u32 = 0o0100000;

pub fn stdin_is_tty() -> bool {
    unsafe { isatty(0) == 1 }
}

pub struct RawMode {
    orig: Termios,
}

impl RawMode {
    pub fn enter() -> io::Result<Self> {
        let mut t: Termios = unsafe { std::mem::zeroed() };
        if unsafe { tcgetattr(0, &mut t as *mut _) } != 0 {
            return Err(io::Error::last_os_error());
        }
        let orig = unsafe { std::ptr::read(&t) };
        t.c_iflag &= !(ICRNL | IXON);
        t.c_oflag &= !OPOST;
        t.c_lflag &= !(ECHO | ICANON | ISIG | IEXTEN);
        if unsafe { tcsetattr(0, TCSANOW, &t as *const _) } != 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(RawMode { orig })
    }
}

impl Drop for RawMode {
    fn drop(&mut self) {
        unsafe {
            tcsetattr(0, TCSANOW, &self.orig as *const _);
        }
    }
}

pub fn term_size() -> (u16, u16) {
    let mut ws = WinSize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    let r = unsafe { ioctl(1, TIOCGWINSZ, &mut ws as *mut _) };
    if r != 0 || ws.ws_row == 0 || ws.ws_col == 0 {
        (24, 80)
    } else {
        (ws.ws_row, ws.ws_col)
    }
}

pub fn read_byte_timeout(ms: i32) -> io::Result<Option<u8>> {
    let mut pfd = PollFd { fd: 0, events: 1, revents: 0 };
    let r = unsafe { poll(&mut pfd as *mut _, 1, ms) };
    if r < 0 {
        return Err(io::Error::last_os_error());
    }
    if r == 0 {
        return Ok(None);
    }
    let mut b = [0u8; 1];
    let n = unsafe { read(0, b.as_mut_ptr(), 1) };
    if n <= 0 {
        Ok(None)
    } else {
        Ok(Some(b[0]))
    }
}

pub fn write_stdout(s: &str) {
    let _ = io::stdout().write_all(s.as_bytes());
}

pub fn flush_stdout() {
    let _ = io::stdout().flush();
}
