#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LangArg {
    English,
    English1k,
    English10k,
}

impl LangArg {
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "english" => Some(LangArg::English),
            "english1k" => Some(LangArg::English1k),
            "english10k" => Some(LangArg::English10k),
            _ => None,
        }
    }
}

pub struct Config {
    pub number_of_words: usize,
    pub number_of_secs: Option<u64>,
    pub number_of_sentences: Option<usize>,
    pub supported_language: LangArg,
    pub prompt: Option<String>,
}

pub enum CliResult {
    Config(Config),
    HelpPrinted,
    VersionPrinted,
    Error(String),
}

const HELP_BODY: &str = "thokr 0.4.1
sleek typing tui with visualized results and historical logging

USAGE:
    {PROG} [OPTIONS]

OPTIONS:
    -f, --full-sentences <NUMBER_OF_SENTENCES>
            number of sentences to use in test

    -h, --help
            Print help information

    -l, --supported-language <SUPPORTED_LANGUAGE>
            language to pull words from [default: english] [possible values: english, english1k,
            english10k]

    -p, --prompt <PROMPT>
            custom prompt to use

    -s, --number-of-secs <NUMBER_OF_SECS>
            number of seconds to run test

    -V, --version
            Print version information

    -w, --number-of-words <NUMBER_OF_WORDS>
            number of words to use in test [default: 15]
";

pub fn help_text(prog: &str) -> String {
    HELP_BODY.replace("{PROG}", prog)
}

pub fn version_text() -> String {
    String::from("thokr 0.4.1\n")
}

fn usage_err(prog: &str) -> String {
    format!(
        "\nUSAGE:\n    {} [OPTIONS]\n\nFor more information try --help\n",
        prog
    )
}

fn usage_err_with(prog: &str, one_liner: &str) -> String {
    format!(
        "\nUSAGE:\n    {} {}\n\nFor more information try --help\n",
        prog, one_liner
    )
}

fn err_unexpected(prog: &str, arg: &str, usage_for: Option<&str>) -> String {
    let hint = if arg.starts_with('-') {
        format!(
            "\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`\n",
            arg, arg
        )
    } else {
        String::new()
    };
    let usage = match usage_for {
        None => usage_err(prog),
        Some(one) => usage_err_with(prog, one),
    };
    format!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n{}{}",
        arg, hint, usage
    )
}

fn err_requires_value(prog: &str, long: &str, placeholder: &str, suffix: &str) -> String {
    format!(
        "error: The argument '--{} <{}>' requires a value but none was supplied{}\n{}",
        long,
        placeholder,
        suffix,
        usage_err(prog)
    )
}

fn err_multiple(prog: &str, long: &str, placeholder: &str) -> String {
    format!(
        "error: The argument '--{} <{}>' was provided more than once, but cannot be used multiple times\n{}",
        long,
        placeholder,
        usage_err(prog)
    )
}

fn err_invalid_value(long: &str, placeholder: &str, val: &str, reason: &str) -> String {
    format!(
        "error: Invalid value \"{}\" for '--{} <{}>': {}\n\nFor more information try --help\n",
        val, long, placeholder, reason
    )
}

fn err_bad_lang(prog: &str, val: &str) -> String {
    format!(
        "error: \"{}\" isn't a valid value for '--supported-language <SUPPORTED_LANGUAGE>'\n\t[possible values: english, english1k, english10k]\n{}",
        val,
        usage_err_with(prog, "--supported-language <SUPPORTED_LANGUAGE>")
    )
}

#[derive(Clone, Copy)]
struct OptDef {
    short: char,
    long: &'static str,
    placeholder: Option<&'static str>,
    value_suffix: &'static str,
}

const OPTS: &[OptDef] = &[
    OptDef {
        short: 'f',
        long: "full-sentences",
        placeholder: Some("NUMBER_OF_SENTENCES"),
        value_suffix: "",
    },
    OptDef {
        short: 'h',
        long: "help",
        placeholder: None,
        value_suffix: "",
    },
    OptDef {
        short: 'l',
        long: "supported-language",
        placeholder: Some("SUPPORTED_LANGUAGE"),
        value_suffix: "\n\t[possible values: english, english1k, english10k]",
    },
    OptDef {
        short: 'p',
        long: "prompt",
        placeholder: Some("PROMPT"),
        value_suffix: "",
    },
    OptDef {
        short: 's',
        long: "number-of-secs",
        placeholder: Some("NUMBER_OF_SECS"),
        value_suffix: "",
    },
    OptDef {
        short: 'V',
        long: "version",
        placeholder: None,
        value_suffix: "",
    },
    OptDef {
        short: 'w',
        long: "number-of-words",
        placeholder: Some("NUMBER_OF_WORDS"),
        value_suffix: "",
    },
];

fn find_long(name: &str) -> Option<OptDef> {
    OPTS.iter().find(|o| o.long == name).copied()
}

fn find_short(c: char) -> Option<OptDef> {
    OPTS.iter().find(|o| o.short == c).copied()
}

fn is_known_arg(s: &str) -> bool {
    if s == "--" || s == "-" {
        return false;
    }
    if let Some(rest) = s.strip_prefix("--") {
        let name = rest.split('=').next().unwrap_or("");
        return find_long(name).is_some();
    }
    if let Some(rest) = s.strip_prefix('-') {
        if let Some(first) = rest.chars().next() {
            return find_short(first).is_some();
        }
    }
    false
}

pub fn parse_args(prog: &str, argv: &[String]) -> CliResult {
    let mut number_of_words: Option<String> = None;
    let mut number_of_secs: Option<String> = None;
    let mut number_of_sentences: Option<String> = None;
    let mut supported_language: Option<String> = None;
    let mut prompt: Option<String> = None;
    let mut help_seen = false;
    let mut version_seen = false;

    // We track whether each option was "seen" (to detect duplicates even if value collection failed)
    let mut seen_w = false;
    let mut seen_s = false;
    let mut seen_f = false;
    let mut seen_l = false;
    let mut seen_p = false;

    let mut i = 0;
    let mut passthrough = false;

    // Helper closures via a small function-like: since borrow checker limits, we use a macro-style block
    while i < argv.len() {
        let a = &argv[i];
        if passthrough {
            return CliResult::Error(err_unexpected(prog, a, None));
        }
        if a == "--" {
            passthrough = true;
            i += 1;
            continue;
        }
        if let Some(body) = a.strip_prefix("--") {
            let (name, embedded_val): (&str, Option<&str>) = if let Some(eq) = body.find('=') {
                (&body[..eq], Some(&body[eq + 1..]))
            } else {
                (body, None)
            };
            let def = match find_long(name) {
                Some(d) => d,
                None => return CliResult::Error(err_unexpected(prog, a, None)),
            };
            match def.long {
                "help" => {
                    if embedded_val.is_some() {
                        return CliResult::Error(err_unexpected(prog, a, None));
                    }
                    if !version_seen {
                        help_seen = true;
                    }
                    i += 1;
                    continue;
                }
                "version" => {
                    if embedded_val.is_some() {
                        return CliResult::Error(err_unexpected(prog, a, None));
                    }
                    if !help_seen {
                        version_seen = true;
                    }
                    i += 1;
                    continue;
                }
                _ => {}
            }
            let placeholder = def.placeholder.unwrap();
            // check duplicate first
            let already_seen = match def.long {
                "number-of-words" => seen_w,
                "number-of-secs" => seen_s,
                "full-sentences" => seen_f,
                "supported-language" => seen_l,
                "prompt" => seen_p,
                _ => false,
            };
            if already_seen {
                return CliResult::Error(err_multiple(prog, def.long, placeholder));
            }
            // Determine value
            let value: String = if let Some(v) = embedded_val {
                v.to_string()
            } else {
                // Peek next arg
                let next = argv.get(i + 1);
                match next {
                    Some(nv) if !is_known_arg(nv) && nv != "--" => {
                        i += 1;
                        nv.clone()
                    }
                    _ => {
