                                        nv,
                                        Some(&format!("--{} <{}>", def.long, placeholder)),
                                    ));
                                }
                            }
                            return CliResult::Error(err_requires_value(
                                prog,
                                def.long,
                                placeholder,
                                def.value_suffix,
                            ));
