#[derive(Clone, Copy)]
struct OptDef {
    short: char,
    long: &'static str,
    placeholder: Option<&'static str>,
    value_suffix: &'static str,
}

const OPTS: &[OptDef] = &[
    OptDef {
        short: 'f',
        long: "full-sentences",
        placeholder: Some("NUMBER_OF_SENTENCES"),
        value_suffix: "",
    },
    OptDef {
        short: 'h',
        long: "help",
        placeholder: None,
        value_suffix: "",
    },
    OptDef {
        short: 'l',
        long: "supported-language",
        placeholder: Some("SUPPORTED_LANGUAGE"),
        value_suffix: "\n\t[possible values: english, english1k, english10k]",
    },
    OptDef {
        short: 'p',
        long: "prompt",
        placeholder: Some("PROMPT"),
        value_suffix: "",
    },
    OptDef {
        short: 's',
        long: "number-of-secs",
        placeholder: Some("NUMBER_OF_SECS"),
        value_suffix: "",
    },
    OptDef {
        short: 'V',
        long: "version",
        placeholder: None,
        value_suffix: "",
    },
    OptDef {
        short: 'w',
        long: "number-of-words",
        placeholder: Some("NUMBER_OF_WORDS"),
        value_suffix: "",
    },
];

fn find_long(name: &str) -> Option<OptDef> {
    OPTS.iter().find(|o| o.long == name).copied()
}

fn find_short(c: char) -> Option<OptDef> {
    OPTS.iter().find(|o| o.short == c).copied()
}

fn is_negative_num(s: &str) -> bool {
    // matches -<digits>
    if let Some(rest) = s.strip_prefix('-') {
        !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit())
    } else {
        false
    }
}

// Returns true if the arg is an option (and should NOT be consumed as a value by default)
fn looks_like_option(s: &str) -> bool {
    if s == "--" || s == "-" {
        return false;
    }
    if s.starts_with('-') {
        if is_negative_num(s) {
            return false;
        }
        return true;
    }
    false
}

pub fn parse_args(prog: &str, argv: &[String]) -> CliResult {
    // Deferred errors (only checked if no help/version at end)
    let mut deferred_err: Option<String> = None;

