                match value {
                    Some(v) => {
                        if already_seen {
                            defer!(err_multiple(prog, def.long, placeholder));
                        } else {
                            match def.long {
                                "full-sentences" => {
                                    seen_f = true;
                                    number_of_sentences = Some(v);
                                }
                                "supported-language" => {
                                    seen_l = true;
                                    supported_language = Some(v);
                                }
                                "prompt" => {
                                    seen_p = true;
                                    prompt = Some(v);
                                }
                                "number-of-secs" => {
                                    seen_s = true;
                                    number_of_secs = Some(v);
                                }
                                "number-of-words" => {
