pub fn parse_args(prog: &str, argv: &[String]) -> CliResult {
    // Deferred errors (only checked if no help/version at end)
    let mut deferred_err: Option<String> = None;

    // Value storage
    let mut number_of_words: Option<String> = None;
    let mut number_of_secs: Option<String> = None;
    let mut number_of_sentences: Option<String> = None;
    let mut supported_language: Option<String> = None;
    let mut prompt: Option<String> = None;

    // Seen flags (for duplicate detection)
    let mut seen_w = false;
    let mut seen_s = false;
    let mut seen_f = false;
    let mut seen_l = false;
    let mut seen_p = false;

    let mut i = 0;
    let mut passthrough = false;

    // Consume next arg as value for the given option, returning the value or Err string.
    // If next arg is unavailable or looks like an option (except negative numbers), return Err.
    macro_rules! defer {
        ($e:expr) => {
            if deferred_err.is_none() {
                deferred_err = Some($e);
            }
        };
    }

    while i < argv.len() {
        let a_own = argv[i].clone();
        let a = a_own.as_str();
        if passthrough {
            return CliResult::Error(err_unexpected(prog, a, None));
        }
        if a == "--" {
            passthrough = true;
            i += 1;
            continue;
        }
        if let Some(body) = a.strip_prefix("--") {
            let (name, embedded_val): (String, Option<String>) = if let Some(eq) = body.find('=') {
                (body[..eq].to_string(), Some(body[eq + 1..].to_string()))
            } else {
                (body.to_string(), None)
            };
            let def = match find_long(&name) {
                Some(d) => d,
                None => return CliResult::Error(err_unexpected(prog, a, None)),
            };
            match def.long {
                "help" => {
                    if embedded_val.is_some() {
                        return CliResult::Error(err_unexpected(prog, a, None));
                    }
                    print!("{}", help_text(prog));
                    return CliResult::HelpPrinted;
                }
                "version" => {
                    if embedded_val.is_some() {
                        return CliResult::Error(err_unexpected(prog, a, None));
                    }
                    print!("{}", version_text());
                    return CliResult::VersionPrinted;
                }
                _ => {}
            }
            let placeholder = def.placeholder.unwrap();
            let already_seen = match def.long {
                "number-of-words" => seen_w,
                "number-of-secs" => seen_s,
                "full-sentences" => seen_f,
                "supported-language" => seen_l,
                "prompt" => seen_p,
                _ => false,
            };
            // Determine value
            let value: Option<String> = if let Some(v) = embedded_val {
                Some(v)
            } else {
                let next = argv.get(i + 1);
                match next {
                    Some(nv) if !looks_like_option(nv) && nv != "--" => {
                        i += 1;
                        Some(nv.clone())
                    }
                    Some(nv) if nv == "-h" || nv == "--help" => {
                        // let help processing continue
                        None
                    }
                    Some(nv) if nv == "-V" || nv == "--version" => {
                        None
                    }
                    Some(nv) if nv.starts_with("--") => {
                        return CliResult::Error(err_unexpected(
                            prog,
                            nv,
                            Some(&format!("--{} <{}>", def.long, placeholder)),
                        ));
                    }
                    Some(nv) => {
                        // short unknown: strip to -x form
                        return CliResult::Error(err_unexpected(prog, nv, None));
                    }
                    None => None,
                }
            };
            match value {
                Some(v) => {
                    if already_seen {
                        defer!(err_multiple(prog, def.long, placeholder));
                    } else {
                        match def.long {
                            "full-sentences" => {
                                seen_f = true;
                                number_of_sentences = Some(v);
                            }
                            "supported-language" => {
                                seen_l = true;
                                supported_language = Some(v);
                            }
                            "prompt" => {
                                seen_p = true;
                                prompt = Some(v);
                            }
                            "number-of-secs" => {
                                seen_s = true;
                                number_of_secs = Some(v);
                            }
                            "number-of-words" => {
                                seen_w = true;
                                number_of_words = Some(v);
                            }
                            _ => unreachable!(),
                        }
                    }
                }
                None => {
                    if already_seen {
                        defer!(err_multiple(prog, def.long, placeholder));
                    } else {
                        defer!(err_requires_value(prog, def.long, placeholder, def.value_suffix));
                        // mark seen so further dup check fires only once
                        match def.long {
                            "full-sentences" => seen_f = true,
                            "supported-language" => seen_l = true,
                            "prompt" => seen_p = true,
                            "number-of-secs" => seen_s = true,
                            "number-of-words" => seen_w = true,
                            _ => {}
                        }
                    }
                }
            }
            i += 1;
        } else if let Some(body) = a.strip_prefix('-') {
            if body.is_empty() {
                return CliResult::Error(err_unexpected(prog, a, None));
            }
            if is_negative_num(a) {
                return CliResult::Error(err_unexpected(prog, a, None));
            }
            let chars: Vec<char> = body.chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let c = chars[j];
                let def = match find_short(c) {
                    Some(d) => d,
                    None => {
                        let s = format!("-{}", c);
                        return CliResult::Error(err_unexpected(prog, &s, None));
                    }
                };
                match def.long {
                    "help" => {
                        print!("{}", help_text(prog));
                        return CliResult::HelpPrinted;
                    }
                    "version" => {
                        print!("{}", version_text());
                        return CliResult::VersionPrinted;
                    }
                    _ => {}
                }
                let placeholder = def.placeholder.unwrap();
                let already_seen = match def.long {
                    "number-of-words" => seen_w,
                    "number-of-secs" => seen_s,
                    "full-sentences" => seen_f,
                    "supported-language" => seen_l,
                    "prompt" => seen_p,
                    _ => false,
                };
                let rest: String = chars[j + 1..].iter().collect();
                let value: Option<String> = if !rest.is_empty() {
                    let v = if rest.starts_with('=') {
                        rest[1..].to_string()
                    } else {
                        rest
                    };
                    Some(v)
                } else {
                    let next = argv.get(i + 1);
                    match next {
                        Some(nv) if !looks_like_option(nv) && nv != "--" => {
                            i += 1;
                            Some(nv.clone())
                        }
                        Some(nv) if nv == "-h" || nv == "--help" => None,
                        Some(nv) if nv == "-V" || nv == "--version" => None,
                        Some(nv) if nv.starts_with("--") => {
                            return CliResult::Error(err_unexpected(
                                prog,
                                nv,
                                Some(&format!("--{} <{}>", def.long, placeholder)),
                            ));
                        }
                        Some(nv) => {
                            return CliResult::Error(err_unexpected(prog, nv, None));
                        }
                        None => None,
                    }
                };
                match value {
                    Some(v) => {
                        if already_seen {
                            defer!(err_multiple(prog, def.long, placeholder));
                        } else {
                            match def.long {
                                "full-sentences" => {
                                    seen_f = true;
                                    number_of_sentences = Some(v);
                                }
                                "supported-language" => {
                                    seen_l = true;
                                    supported_language = Some(v);
                                }
                                "prompt" => {
                                    seen_p = true;
                                    prompt = Some(v);
                                }
                                "number-of-secs" => {
                                    seen_s = true;
                                    number_of_secs = Some(v);
                                }
                                "number-of-words" => {
                                    seen_w = true;
                                    number_of_words = Some(v);
                                }
                                _ => unreachable!(),
                            }
                        }
                    }
                    None => {
                        if already_seen {
                            defer!(err_multiple(prog, def.long, placeholder));
                        } else {
                            defer!(err_requires_value(
                                prog,
                                def.long,
                                placeholder,
                                def.value_suffix
                            ));
                            match def.long {
                                "full-sentences" => seen_f = true,
                                "supported-language" => seen_l = true,
                                "prompt" => seen_p = true,
                                "number-of-secs" => seen_s = true,
                                "number-of-words" => seen_w = true,
                                _ => {}
                            }
                        }
                    }
                }
                break;
            }
            i += 1;
        } else {
            return CliResult::Error(err_unexpected(prog, a, None));
        }
    }

    if let Some(e) = deferred_err {
        return CliResult::Error(e);
    }

    let number_of_words: usize = match number_of_words {
        None => 15,
        Some(s) => match s.parse::<usize>() {
            Ok(v) => v,
            Err(e) => {
                return CliResult::Error(err_invalid_value(
                    "number-of-words",
                    "NUMBER_OF_WORDS",
                    &s,
                    &e.to_string(),
                ));
            }
        },
    };
    let number_of_secs: Option<u64> = match number_of_secs {
        None => None,
        Some(s) => match s.parse::<u64>() {
            Ok(v) => Some(v),
            Err(e) => {
                return CliResult::Error(err_invalid_value(
                    "number-of-secs",
                    "NUMBER_OF_SECS",
                    &s,
                    &e.to_string(),
                ));
            }
        },
    };
    let number_of_sentences: Option<usize> = match number_of_sentences {
        None => None,
        Some(s) => match s.parse::<usize>() {
            Ok(v) => Some(v),
            Err(e) => {
                return CliResult::Error(err_invalid_value(
                    "full-sentences",
                    "NUMBER_OF_SENTENCES",
                    &s,
                    &e.to_string(),
                ));
            }
        },
    };
    let supported_language = match supported_language {
        None => LangArg::English,
        Some(s) => match LangArg::from_str(&s) {
            Some(v) => v,
            None => return CliResult::Error(err_bad_lang(prog, &s)),
        },
    };

    CliResult::Config(Config {
        number_of_words,
        number_of_secs,
        number_of_sentences,
        supported_language,
        prompt,
    })
}
