                let def = match find_short(c) {
                    Some(d) => d,
                    None => {
                        let s = format!("-{}", c);
                        return CliResult::Error(err_unexpected(prog, &s, None));
                    }
                };
                match def.long {
                    "help" => {
                        print!("{}", help_text(prog));
                        return CliResult::HelpPrinted;
                    }
                    "version" => {
                        print!("{}", version_text());
                        return CliResult::VersionPrinted;
                    }
                    _ => {}
                }
