                let def_idx = opt_index(&def);
                st.count[def_idx] += 1;
                let rest: String = chars[j + 1..].iter().collect();
                let value: Option<String> = if !rest.is_empty() {
                    let v = if rest.starts_with('=') { rest[1..].to_string() } else { rest };
                    Some(v)
                } else {
                    let next = argv.get(i + 1);
                    match next {
                        Some(nv) if !looks_like_option(nv) && nv != "--" => {
                            i += 1;
                            Some(nv.clone())
                        }
                        Some(nv) => {
                            if nv == "-h" || nv == "--help" || nv == "-V" || nv == "--version" {
                                None
                            } else if nv.starts_with("--") {
