                        def.long,
                        def.placeholder.unwrap(),
                        v,
                        &e.to_string(),
                    ));
                }
            }
            "supported-language" => {
                if LangArg::from_str(v).is_none() {
                    return CliResult::Error(err_bad_lang(prog, v));
                }
            }
            _ => {}
        }
    }

    // Duplicate check (in option definition order)
    for (idx, d) in OPTS.iter().enumerate() {
        if d.long == "help" || d.long == "version" { continue; }
        if st.count[idx] > 1 {
            return CliResult::Error(err_multiple(prog, d.long, d.placeholder.unwrap()));
        }
    }

    // Requires value check (in option definition order)
    for (idx, d) in OPTS.iter().enumerate() {
        if d.long == "help" || d.long == "version" { continue; }
        if st.count[idx] > 0 && st.with_value[idx] == 0 {
            return CliResult::Error(err_requires_value(
                prog, d.long, d.placeholder.unwrap(), d.value_suffix,
            ));
        }
    }

    // Build config
    let mut number_of_words: usize = 15;
    let mut number_of_secs: Option<u64> = None;
    let mut number_of_sentences: Option<usize> = None;
    let mut supported_language = LangArg::English;
    let mut prompt: Option<String> = None;

    // Use first value for each
    let mut seen: [bool; 7] = [false; 7];
    for (def, v) in st.values.into_iter() {
        let idx = opt_index(def);
        if seen[idx] { continue; }
        seen[idx] = true;
        match def.long {
            "number-of-words" => number_of_words = v.parse().unwrap(),
            "number-of-secs" => number_of_secs = Some(v.parse().unwrap()),
            "full-sentences" => number_of_sentences = Some(v.parse().unwrap()),
            "supported-language" => supported_language = LangArg::from_str(&v).unwrap(),
            "prompt" => prompt = Some(v),
            _ => {}
        }
    }

    CliResult::Config(Config {
        number_of_words,
        number_of_secs,
        number_of_sentences,
        supported_language,
        prompt,
    })
}
