use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Outcome {
    Correct,
    Incorrect,
    Pending,
}

#[derive(Debug, Clone, Copy)]
pub struct Input {
    pub char: char,
    pub outcome: Outcome,
    pub timestamp: Duration, // since start
}

pub struct Thok {
    pub prompt: String,
    pub prompt_chars: Vec<char>,
    pub cursor: usize,
    pub inputs: Vec<Input>,
    pub started: Option<Instant>,
    pub time_limit: Option<Duration>,
    pub finished: bool,
    pub wpm: f64,
    pub accuracy: f64,
    pub std_dev: f64,
    pub wpm_points: Vec<(f64, f64)>, // (seconds, wpm)
}

impl Thok {
    pub fn new(prompt: String, time_limit: Option<Duration>) -> Self {
        let prompt_chars: Vec<char> = prompt.chars().collect();
        Thok {
            prompt,
            prompt_chars,
            cursor: 0,
            inputs: Vec::new(),
            started: None,
            time_limit,
            finished: false,
            wpm: 0.0,
            accuracy: 0.0,
            std_dev: 0.0,
            wpm_points: Vec::new(),
        }
    }

    pub fn has_started(&self) -> bool {
        self.started.is_some()
    }

    pub fn write(&mut self, c: char) {
        if self.finished {
            return;
        }
        if self.started.is_none() {
            self.started = Some(Instant::now());
        }
        let elapsed = self.started.unwrap().elapsed();
        let outcome = if self.cursor < self.prompt_chars.len() {
            if self.prompt_chars[self.cursor] == c {
                Outcome::Correct
            } else {
                Outcome::Incorrect
            }
        } else {
            Outcome::Incorrect
        };
        self.inputs.push(Input {
            char: c,
            outcome,
            timestamp: elapsed,
        });
        self.cursor += 1;
        if self.cursor >= self.prompt_chars.len() {
            self.finish();
        }
    }

    pub fn backspace(&mut self) {
        if self.cursor > 0 {
            self.cursor -= 1;
            self.inputs.pop();
        }
    }

    pub fn elapsed_secs(&self) -> f64 {
        match self.started {
            None => 0.0,
            Some(t) => t.elapsed().as_secs_f64(),
        }
    }

    pub fn time_up(&self) -> bool {
        if let (Some(t), Some(lim)) = (self.started, self.time_limit) {
            t.elapsed() >= lim
        } else {
            false
        }
    }

    pub fn finish(&mut self) {
        if self.finished { return; }
        self.finished = true;
        self.calc_stats();
    }

    fn calc_stats(&mut self) {
        // WPM = (correct chars / 5) / (minutes)
        let elapsed = self.elapsed_secs();
        let correct_chars = self.inputs.iter().filter(|i| i.outcome == Outcome::Correct).count();
        let total_chars = self.inputs.len();
        if elapsed <= 0.0 {
            self.wpm = f64::INFINITY;
        } else {
            let minutes = elapsed / 60.0;
            self.wpm = (correct_chars as f64 / 5.0) / minutes;
        }
        self.accuracy = if total_chars == 0 {
            100.0
        } else {
