// Simple PRNG based on SplitMix64, seeded from time + getpid.

use std::time::{SystemTime, UNIX_EPOCH};

pub struct Rng {
    state: u64,
}

impl Rng {
    pub fn new() -> Self {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0);
        let pid = unsafe { libc_getpid() } as u64;
        let mut seed = nanos ^ pid.wrapping_mul(0x9E3779B97F4A7C15);
        if seed == 0 { seed = 1; }
        Rng { state: seed }
    }

    pub fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        z ^ (z >> 31)
    }

    pub fn range(&mut self, n: usize) -> usize {
        (self.next_u64() % n as u64) as usize
    }

    pub fn choice<'a, T>(&mut self, slice: &'a [T]) -> &'a T {
        let i = self.range(slice.len());
        &slice[i]
    }
}

unsafe extern "C" {
    #[link_name = "getpid"]
    fn libc_getpid() -> i32;
}
RUSTEOF

