use cli::{parse_args, CliResult};
use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();
    let prog = args
        .get(0)
        .and_then(|s| s.rsplit('/').next())
        .unwrap_or("thokr")
        .to_string();

    let cfg = match parse_args(&prog, &args[1..]) {
        CliResult::Config(c) => c,
        CliResult::HelpPrinted => return ExitCode::from(0),
        CliResult::VersionPrinted => return ExitCode::from(0),
        CliResult::Error(msg) => {
            eprint!("{}", msg);
            return ExitCode::from(2);
        }
    };

    if !terminal::stdin_is_tty() {
        eprintln!("error: stdin must be a tty");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    thokr [OPTIONS]");
        eprintln!();
        eprintln!("For more information try --help");
        return ExitCode::from(2);
    }

    match ui::run(cfg) {
        Ok(()) => ExitCode::from(0),
        Err(e) => {
            eprintln!("error: {}", e);
            ExitCode::from(1)
        }
    }
}
