cat > src/ui.rs << 'RUSTEOF'
use crate::cli::Config;
use crate::lang;
use crate::rng::Rng;
use crate::terminal;
use crate::thok::{Outcome, Thok};
use std::io::Write;
use std::time::{Duration, Instant};

const ENTER_ALT_SCREEN: &str = "\x1b[?1049h";
const EXIT_ALT_SCREEN: &str = "\x1b[?1049l";
const HIDE_CURSOR: &str = "\x1b[?25l";
const SHOW_CURSOR: &str = "\x1b[?25h";
const RESET_STYLE: &str = "\x1b[0m\x1b[39m\x1b[49m";
const CLEAR_SCREEN: &str = "\x1b[2J\x1b[H";

pub enum Key {
    Char(char),
    Backspace,
    Left,
    Right,
    Escape,
    Other,
}

fn read_key() -> Option<Key> {
    let b = terminal::read_byte_timeout(100).ok().flatten()?;
    match b {
        0x7f | 0x08 => Some(Key::Backspace),
        0x1b => {
            // Possible escape sequence
            let b1 = terminal::read_byte_timeout(50).ok().flatten();
            match b1 {
                Some(b'[') => {
                    let b2 = terminal::read_byte_timeout(50).ok().flatten();
                    match b2 {
                        Some(b'D') => Some(Key::Left),
                        Some(b'C') => Some(Key::Right),
                        _ => Some(Key::Other),
                    }
                }
                None => Some(Key::Escape),
                _ => Some(Key::Escape),
            }
        }
        0x03 => Some(Key::Escape), // Ctrl-C
        b if b < 0x20 => Some(Key::Other),
        b if b < 0x80 => Some(Key::Char(b as char)),
        _ => {
            // UTF-8 continuation
            let extra = if b >= 0xF0 { 3 } else if b >= 0xE0 { 2 } else if b >= 0xC0 { 1 } else { 0 };
            let mut buf = vec![b];
            for _ in 0..extra {
                if let Some(nb) = terminal::read_byte_timeout(50).ok().flatten() {
                    buf.push(nb);
                }
            }
            let s = String::from_utf8(buf).ok()?;
            s.chars().next().map(Key::Char)
        }
    }
}

fn goto(row: u16, col: u16) -> String {
    format!("\x1b[{};{}H", row, col)
}

fn render_typing(thok: &Thok) {
    let (rows, cols) = terminal::term_size();
    let cols = cols as usize;
    let mut out = String::new();
    out.push_str(CLEAR_SCREEN);
    out.push_str(HIDE_CURSOR);

    // Word-wrap the prompt into lines that fit within `cols`
    let prompt: &str = &thok.prompt;
    let lines: Vec<String> = wrap_words(prompt, cols.saturating_sub(4).max(1));

    // Vertical centering
    let total_lines = lines.len();
    let start_row = if total_lines >= rows as usize {
        1
    } else {
        ((rows as usize - total_lines) / 2) as u16 + 1
    };

    // For each line, compute starting column and emit characters with styling
    // We need to track cursor position across lines.
    let mut char_pos = 0usize;
    for (li, line) in lines.iter().enumerate() {
        let line_chars: Vec<char> = line.chars().collect();
        let width = line_chars.len();
        let start_col = if width >= cols { 1 } else { ((cols - width) / 2) as u16 + 1 };
        let row = start_row + li as u16;
        out.push_str(&goto(row, start_col));
        for c in line_chars.iter() {
            let idx = char_pos;
            let styled = style_char(*c, idx, thok);
            out.push_str(&styled);
            char_pos += 1;
        }
        // account for the wrap-skipped space between wrapped lines
        // We used wrap_words that consumes one space between lines, so we need to
        // also count that space in the prompt position.
        if li + 1 < lines.len() {
            // There was a space character from the original prompt that got consumed by wrap
            char_pos += 1;
        }
    }
    out.push_str(RESET_STYLE);

    let _ = std::io::stdout().write_all(out.as_bytes());
    let _ = std::io::stdout().flush();
}

fn style_char(c: char, idx: usize, thok: &Thok) -> String {
    // Determine style based on typing progress
    if idx < thok.cursor {
        // Already typed
        let input = &thok.inputs[idx];
        match input.outcome {
            Outcome::Correct => format!("\x1b[1m\x1b[38;5;2m{}", c),
            Outcome::Incorrect => {
                // For spaces, show the expected char in red instead (visual hint)
                if thok.prompt_chars[idx] == ' ' {
                    format!("\x1b[1m\x1b[38;5;1m_")
                } else {
                    format!("\x1b[1m\x1b[38;5;1m{}", escape_char(c))
                }
            }
            Outcome::Pending => format!("{}", c),
        }
    } else if idx == thok.cursor {
        // Cursor position: dim + bold + underline
        format!("\x1b[0;1;2;4m{}\x1b[24m", escape_char(c))
    } else {
        // Pending
        format!("\x1b[0;1;2m{}", escape_char(c))
    }
}

fn escape_char(c: char) -> String {
    c.to_string()
}

fn wrap_words(s: &str, width: usize) -> Vec<String> {
    if width == 0 { return vec![s.to_string()]; }
    let words: Vec<&str> = s.split(' ').collect();
    let mut lines: Vec<String> = Vec::new();
    let mut cur = String::new();
    for (i, w) in words.iter().enumerate() {
        let need = if cur.is_empty() { w.chars().count() } else { cur.chars().count() + 1 + w.chars().count() };
        if need <= width {
            if !cur.is_empty() { cur.push(' '); }
            cur.push_str(w);
        } else {
            if !cur.is_empty() {
                lines.push(cur);
            }
            // If word itself is longer than width, break it
            if w.chars().count() > width {
                let mut chars: Vec<char> = w.chars().collect();
                while chars.len() > width {
                    let chunk: String = chars.drain(..width).collect();
                    lines.push(chunk);
                }
                cur = chars.into_iter().collect();
            } else {
                cur = w.to_string();
            }
        }
        let _ = i;
    }
    if !cur.is_empty() {
        lines.push(cur);
    }
    if lines.is_empty() {
        lines.push(String::new());
    }
    lines
}

fn render_results(thok: &Thok) {
    let (rows, cols) = terminal::term_size();
    let mut out = String::new();
    out.push_str(CLEAR_SCREEN);

    let rows = rows as usize;
    let cols = cols as usize;

    // Graph area - placeholder. Render a simple text summary centered.
    let wpm = thok.wpm;
    let acc = thok.accuracy;
    let sd = thok.std_dev;
    let stats = if wpm.is_infinite() {
        format!("inf wpm   {:.0}% acc   {:.2} sd", acc, sd)
    } else {
        format!("{:.0} wpm   {:.0}% acc   {:.2} sd", wpm, acc, sd)
    };

    // Draw a minimalist layout. Top left: WPM value; bottom: seconds; center bar; footer: stats + hint
    let stats_row = rows.saturating_sub(5);
    let footer_row = rows.saturating_sub(3);
    let hint = "(r)etry / (n)ew / (esc)ape";

    // Y axis
    out.push_str(&goto(2, 6));
    if wpm.is_infinite() {
        out.push_str("\x1b[1minf\x1b[0m\x1b[39m\x1b[49m");
    } else {
        out.push_str(&format!("\x1b[1m{:.0}\x1b[0m\x1b[39m\x1b[49m", wpm));
    }
    out.push('|');
    out.push_str("wpm");
    // X axis endings
    let x_label_row = rows.saturating_sub(7);
    out.push_str(&goto(x_label_row as u16, 6));
    out.push_str("\x1b[1m0\x1b[0m\x1b[39m\x1b[49m  |");
    // pad to right with "seconds"
    let sec_col = cols.saturating_sub(9);
    out.push_str(&goto(x_label_row as u16, sec_col as u16));
    out.push_str("seconds");
    // horizontal axis
    out.push_str(&goto((x_label_row + 1) as u16, 9));
    let mut axis = String::new();
    axis.push_str("└");
    for _ in 0..cols.saturating_sub(10) { axis.push_str("─"); }
    out.push_str(&axis);

    // Ticks
    out.push_str(&goto((x_label_row + 2) as u16, 9));
    out.push_str("\x1b[1m1\x1b[0m\x1b[39m\x1b[49m");
    if !thok.wpm_points.is_empty() {
        let total_sec = thok.wpm_points.last().unwrap().0;
        let right_label = format!("{:.2}", total_sec);
        let rc = cols.saturating_sub(right_label.chars().count() + 1);
        out.push_str(&goto((x_label_row + 2) as u16, rc as u16));
        out.push_str(&format!("\x1b[1m{}\x1b[0m\x1b[39m\x1b[49m", right_label));
    }

    // Stats centered
    let stats_col = if cols > stats.chars().count() { (cols - stats.chars().count()) / 2 } else { 0 };
    out.push_str(&goto(stats_row as u16, (stats_col + 1) as u16));
    out.push_str(&format!("\x1b[1m{}\x1b[0m\x1b[39m\x1b[49m", stats));

    // Hint
    out.push_str(&goto(footer_row as u16, 6));
    out.push_str(&format!("\x1b[3m{}\x1b[0m\x1b[39m\x1b[49m", hint));

    let _ = std::io::stdout().write_all(out.as_bytes());
    let _ = std::io::stdout().flush();
}

fn log_csv(cfg: &Config, thok: &Thok) -> std::io::Result<()> {
    let cfg_dir = config_dir()?;
    std::fs::create_dir_all(&cfg_dir)?;
    let path = std::path::Path::new(&cfg_dir).join("log.csv");
    let exists = path.exists();
    let mut f = std::fs::OpenOptions::new().create(true).append(true).open(&path)?;
    if !exists {
        writeln!(f, "date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev")?;
    }
    let date = current_date_string();
    let num_secs = match cfg.number_of_secs {
        Some(n) => n.to_string(),
        None => String::new(),
    };
    let wpm_str = if thok.wpm.is_infinite() { "inf".to_string() } else { format!("{:.0}", thok.wpm) };
    let line = format!(
        "{},{},{},{:.2},{},{:.0},{:.2}\n",
        date,
        cfg.number_of_words,
        num_secs,
        thok.elapsed_secs(),
        wpm_str,
        thok.accuracy,
        thok.std_dev,
    );
    f.write_all(line.as_bytes())?;
    Ok(())
}

fn config_dir() -> std::io::Result<String> {
    if let Ok(x) = std::env::var("XDG_CONFIG_HOME") {
        if !x.is_empty() {
            return Ok(format!("{}/thokr", x));
        }
    }
    if let Ok(h) = std::env::var("HOME") {
        return Ok(format!("{}/.config/thokr", h));
    }
    Ok(".config/thokr".to_string())
}

fn current_date_string() -> String {
    // Produce something like "Thu May  7 20:14:09 2026"
    // Match the format of libc's ctime(3)
    unsafe {
        let mut t: i64 = 0;
        libc_time(&mut t as *mut i64);
        let s = libc_ctime(&t as *const i64);
        if s.is_null() { return "".to_string(); }
        let mut len = 0;
        while *s.offset(len) != 0 { len += 1; }
