fn current_date_string() -> String {
    // Produce something like "Thu May  7 20:14:09 2026"
    // Match the format of libc's ctime(3)
    unsafe {
        let mut t: i64 = 0;
        libc_time(&mut t as *mut i64);
        let s = libc_ctime(&t as *const i64);
        if s.is_null() { return "".to_string(); }
        let mut len = 0;
        while *s.offset(len) != 0 { len += 1; }
        let slice = std::slice::from_raw_parts(s as *const u8, len as usize);
        let st = String::from_utf8_lossy(slice).to_string();
        // ctime includes trailing newline
        st.trim_end_matches('\n').to_string()
    }
}

unsafe extern "C" {
    fn libc_time(tloc: *mut i64) -> i64;
    fn libc_ctime(t: *const i64) -> *const i8;
}

// Map libc names via linker - but our externs are renamed. Use link_name
// Actually we need to match "time" and "ctime" symbols.

pub fn run(cfg: Config) -> std::io::Result<()> {
    let mut rng = Rng::new();

    // Enter alternate screen and raw mode
    let _raw = terminal::RawMode::enter()?;
    {
        let mut o = std::io::stdout();
        o.write_all(ENTER_ALT_SCREEN.as_bytes())?;
        o.write_all(HIDE_CURSOR.as_bytes())?;
        o.flush()?;
    }

    let exit_code = run_loop(&cfg, &mut rng);

    // Leave alternate screen and restore cursor
    {
        let mut o = std::io::stdout();
        let _ = o.write_all(RESET_STYLE.as_bytes());
        let _ = o.write_all(SHOW_CURSOR.as_bytes());
        let _ = o.write_all(EXIT_ALT_SCREEN.as_bytes());
        let _ = o.flush();
    }
    exit_code
}

fn run_loop(cfg: &Config, rng: &mut Rng) -> std::io::Result<()> {
    loop {
        let prompt = lang::make_prompt(cfg, rng);
        let time_limit = cfg.number_of_secs.map(|n| Duration::from_secs(n));
        let mut thok = Thok::new(prompt, time_limit);
        let mut last_draw = Instant::now() - Duration::from_secs(1);

        // Typing phase
        loop {
            if thok.time_up() && !thok.finished {
                thok.finish();
            }
            if thok.finished {
                break;
            }
            if last_draw.elapsed() >= Duration::from_millis(50) {
                render_typing(&thok);
                last_draw = Instant::now();
            }
            match read_key() {
                Some(Key::Char(c)) => {
                    thok.write(c);
                }
                Some(Key::Backspace) => {
                    thok.backspace();
                }
                Some(Key::Escape) => {
                    return Ok(());
                }
                Some(Key::Left) => {
                    // Restart with same prompt
                    break;
                }
                Some(Key::Right) => {
                    // New prompt (only if no custom prompt)
                    if cfg.prompt.is_none() { break; }
                }
                _ => {}
            }
        }

        if !thok.finished {
            // left/right was pressed before finishing; go to top
            continue;
        }

        // Results phase
        render_results(&thok);
        let _ = log_csv(cfg, &thok);

        loop {
            match read_key() {
                Some(Key::Char('r')) => {
                    break;
                }
                Some(Key::Char('n')) => {
                    if cfg.prompt.is_some() {
                        return Ok(());
                    }
                    // regenerate
                    break;
                }
                Some(Key::Escape) => {
                    return Ok(());
                }
                _ => {}
            }
        }
    }
}
