            }
        }

        if !thok.finished {
            // left/right was pressed before finishing; go to top
            continue;
        }

        // Results phase
        render_results(&thok);
        let _ = log_csv(cfg, &thok);

        loop {
            match read_key() {
                Some(Key::Char('r')) => {
                    break;
                }
                Some(Key::Char('n')) => {
                    if cfg.prompt.is_some() {
                        return Ok(());
                    }
                    // regenerate
                    break;
                }
                Some(Key::Escape) => {
                    return Ok(());
                }
                _ => {}
            }
        }
    }
