    let wpm_top: String = if thok.wpm.is_infinite() || thok.wpm.is_nan() {
        "inf".to_string()
    } else {
        format!("{:.0}", thok.wpm)
    };
    let wpm_bottom = "0".to_string();

    // Y-axis label column: 6-8. Value is left-aligned, pad right with spaces so "│" sits at col 9.
    let yval_width = 3usize;
    let yaxis_col = 9u16;
    let chart_start_col = yaxis_col + 1; // 10

    // Row 3 top axis
    let top_row = 3u16;
    let bottom_row = (rows as i32 - 7).max(1) as u16;
    let hbar_row = (rows as i32 - 6).max(1) as u16;
    let tick_row = (rows as i32 - 5).max(1) as u16;
    let stats_row = (rows as i32 - 4).max(1) as u16;
    let hint_row = (rows as i32 - 2).max(1) as u16;

    // Top-left "inf" (or wpm)
    out.push_str(&goto(top_row, 6));
    out.push_str(&format!("\\x1b[1m{}\\x1b[0m\\x1b[39m\\x1b[49m", wpm_top));
    // wpm text at col 10
    out.push_str(&goto(top_row, chart_start_col));
    out.push_str("wpm");

    // Vertical axis from top_row+1 to bottom_row
    for r in top_row..=bottom_row {
        out.push_str(&goto(r, yaxis_col));
        out.push_str("│");
    }

    // Bottom-left "0"
    out.push_str(&goto(bottom_row, 6));
    out.push_str(&format!("\\x1b[1m{}\\x1b[0m\\x1b[39m\\x1b[49m", wpm_bottom));
    // Padding to col 9 and axis already placed above, now add "seconds" at right
    let sec_label = "seconds";
    let sec_start = (cols as i32 - sec_label.chars().count() as i32 + 1).max(1) as u16;
    out.push_str(&goto(bottom_row, sec_start));
    out.push_str(sec_label);

    // Horizontal bar row
    out.push_str(&goto(hbar_row, yaxis_col));
